alter table public.calidad_no_conformidades add column if not exists origen text not null default 'Ejecución', add column if not exists impacto text not null default 'Calidad', add column if not exists correccion_inmediata text, add column if not exists metodo_causa_raiz text not null default '5 Porqués', add column if not exists causa_categoria text not null default 'Método / Procedimiento', add column if not exists eficacia_verificada boolean not null default false, add column if not exists fecha_verificacion timestamptz, add column if not exists fecha_verificacion_eficacia date, add column if not exists observacion_verificacion text, add column if not exists trazabilidad jsonb not null default '[]'::jsonb;
create index if not exists calidad_nc_empresa_obra_estado_idx on public.calidad_no_conformidades (empresa, obra_nombre, estado);
create index if not exists calidad_nc_empresa_obra_causa_idx on public.calidad_no_conformidades (empresa, obra_nombre, causa_categoria, partida);
drop policy if exists "Allow_All_Operations_Anon_Authenticated" on public.calidad_no_conformidades;
drop policy if exists "calidad_nc_empresa_select" on public.calidad_no_conformidades;
drop policy if exists "calidad_nc_empresa_insert" on public.calidad_no_conformidades;
drop policy if exists "calidad_nc_empresa_update" on public.calidad_no_conformidades;
drop policy if exists "calidad_nc_empresa_delete" on public.calidad_no_conformidades;
create policy "calidad_nc_empresa_select" on public.calidad_no_conformidades for select to authenticated using (exists (select 1 from public.usuarios u where u.auth_user_id=(select auth.uid()) and (u.empresa=calidad_no_conformidades.empresa or lower(coalesce(u.rol_base,u.rol,''))='superusuario')));
create policy "calidad_nc_empresa_insert" on public.calidad_no_conformidades for insert to authenticated with check (exists (select 1 from public.usuarios u where u.auth_user_id=(select auth.uid()) and (u.empresa=calidad_no_conformidades.empresa or lower(coalesce(u.rol_base,u.rol,''))='superusuario')));
create policy "calidad_nc_empresa_update" on public.calidad_no_conformidades for update to authenticated using (exists (select 1 from public.usuarios u where u.auth_user_id=(select auth.uid()) and (u.empresa=calidad_no_conformidades.empresa or lower(coalesce(u.rol_base,u.rol,''))='superusuario'))) with check (exists (select 1 from public.usuarios u where u.auth_user_id=(select auth.uid()) and (u.empresa=calidad_no_conformidades.empresa or lower(coalesce(u.rol_base,u.rol,''))='superusuario')));
create policy "calidad_nc_empresa_delete" on public.calidad_no_conformidades for delete to authenticated using (exists (select 1 from public.usuarios u where u.auth_user_id=(select auth.uid()) and (u.empresa=calidad_no_conformidades.empresa or lower(coalesce(u.rol_base,u.rol,''))='superusuario')));
revoke all on public.calidad_no_conformidades from anon;
grant select,insert,update,delete on public.calidad_no_conformidades to authenticated;
grant usage,select on sequence public.calidad_no_conformidades_id_seq to authenticated;;
